{
  "version": 3,
  "sources": ["src/app/administrativo/dashboard/dashboard.component.css"],
  "sourcesContent": ["   .dashboard-container {\n      width: 100%;\n      padding: 0 20px;\n      margin: 0;\n    }\n\n    .stats-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n      gap: 20px;\n      margin-bottom: 30px;\n    }\n\n    .stat-card {\n      background: white;\n      border-radius: 12px;\n      padding: 25px;\n      display: flex;\n      align-items: center;\n      gap: 20px;\n      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);\n    }\n\n    .stat-icon {\n      width: 60px;\n      height: 60px;\n      border-radius: 12px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 24px;\n      color: white;\n    }\n\n    .stat-icon.pending { background: #f39c12; }\n    .stat-icon.processing { background: #3498db; }\n    .stat-icon.completed { background: #27ae60; }\n    .stat-icon.rejected { background: #e74c3c; }\n\n    .stat-content h3 {\n      font-size: 32px;\n      font-weight: 700;\n      margin: 0;\n      color: #2c3e50;\n    }\n\n    .stat-content p {\n      font-size: 14px;\n      color: #7f8c8d;\n      margin: 4px 0 0 0;\n    }\n\n    .content-grid {\n      display: grid;\n      grid-template-columns: 2fr 1fr;\n      gap: 20px;\n    }\n\n    .card {\n      background: white;\n      border-radius: 12px;\n      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);\n      overflow: hidden;\n    }\n\n    .card-header {\n      padding: 20px 25px;\n      border-bottom: 1px solid #f1f2f6;\n      background: #fafbfc;\n    }\n\n    .card-header h3 {\n      margin: 0;\n      font-size: 18px;\n      font-weight: 600;\n      color: #2c3e50;\n    }\n\n    .card-content {\n      padding: 25px;\n    }\n\n    .tramites-list {\n      display: flex;\n      flex-direction: column;\n      gap: 15px;\n    }\n\n    .tramite-item {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 15px;\n      background: #f8f9fa;\n      border-radius: 8px;\n      border-left: 4px solid #f39c12;\n    }\n\n    .tramite-title {\n      font-weight: 600;\n      color: #2c3e50;\n      margin-bottom: 4px;\n    }\n\n    .tramite-user {\n      font-size: 14px;\n      color: #7f8c8d;\n      margin-bottom: 2px;\n    }\n\n    .tramite-date {\n      font-size: 12px;\n      color: #95a5a6;\n    }\n\n    .tramite-metadata {\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n      margin: 8px 0;\n    }\n\n    .tramite-tipo,\n    .tramite-area,\n    .tramite-usuario-tipo {\n      font-size: 11px;\n      padding: 2px 6px;\n      border-radius: 4px;\n      background: #f1f2f6;\n      color: #2c3e50;\n      display: inline-block;\n      max-width: fit-content;\n    }\n\n    .tramite-tipo {\n      background: #e3f2fd;\n      color: #1976d2;\n    }\n\n    .tramite-area {\n      background: #f3e5f5;\n      color: #7b1fa2;\n    }\n\n    .tramite-usuario-tipo {\n      background: #fff3e0;\n      color: #f57c00;\n    }\n\n    .btn {\n      padding: 6px 12px;\n      border: none;\n      border-radius: 6px;\n      font-size: 12px;\n      font-weight: 500;\n      cursor: pointer;\n      transition: all 0.3s ease;\n    }\n\n    .btn-primary {\n      background: #3498db;\n      color: white;\n    }\n\n    .btn-primary:hover {\n      background: #2980b9;\n    }\n\n    .actions-list {\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n\n    .action-item {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      padding: 15px;\n      background: #f8f9fa;\n      border: none;\n      border-radius: 8px;\n      cursor: pointer;\n      transition: all 0.3s ease;\n    }\n\n    .action-item:hover {\n      background: #e74c3c;\n      color: white;\n    }\n\n    .action-item i {\n      color: #e74c3c;\n      transition: color 0.3s ease;\n    }\n\n    .action-item:hover i {\n      color: white;\n    }\n\n    /* USUARIO-specific styles */\n    .usuario-content {\n      grid-template-columns: 1.5fr 1fr;\n      gap: 25px;\n    }\n\n    .tramite-progress {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      margin-top: 10px;\n    }\n\n    .progress-bar {\n      flex: 1;\n      height: 8px;\n      background: #f1f2f6;\n      border-radius: 4px;\n      overflow: hidden;\n    }\n\n    .progress-fill {\n      height: 100%;\n      background: linear-gradient(90deg, #27ae60, #2ecc71);\n      transition: width 0.3s ease;\n    }\n\n    .progress-text {\n      font-size: 12px;\n      font-weight: 600;\n      color: #334155;\n      min-width: 35px;\n    }\n\n    .estado-badge {\n      padding: 4px 8px;\n      border-radius: 12px;\n      font-size: 11px;\n      font-weight: 600;\n      text-transform: uppercase;\n    }\n\n    .estado-proceso {\n      background: #3498db;\n      color: white;\n    }\n\n    .estado-completado {\n      background: #27ae60;\n      color: white;\n    }\n\n    .estado-observado {\n      background: #f39c12;\n      color: white;\n    }\n\n    .estado-rechazado {\n      background: #e74c3c;\n      color: white;\n    }\n\n    .estado-aprobado {\n      background: #27ae60;\n      color: white;\n    }\n\n    .card-footer {\n      padding: 15px 25px;\n      border-top: 1px solid #f1f2f6;\n      background: #fafbfc;\n      text-align: center;\n    }\n\n    .status-list {\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n    }\n\n    .status-item {\n      display: flex;\n      align-items: center;\n      gap: 15px;\n      padding: 12px;\n      background: #f8f9fa;\n      border-radius: 8px;\n    }\n\n    .status-icon {\n      width: 40px;\n      height: 40px;\n      border-radius: 8px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: white;\n      font-size: 16px;\n    }\n\n    .status-approved {\n      background: #27ae60;\n    }\n\n    .status-review {\n      background: #3498db;\n    }\n\n    .status-action {\n      background: #f39c12;\n    }\n\n    .status-processing {\n      background: #3498db;\n    }\n\n    .status-completed {\n      background: #27ae60;\n    }\n\n    .status-rejected {\n      background: #e74c3c;\n    }\n\n    .status-title {\n      font-weight: 600;\n      color: #2c3e50;\n      margin-bottom: 2px;\n    }\n\n    .status-count {\n      font-size: 12px;\n      color: #7f8c8d;\n    }\n\n    /* Expired tramites styles */\n    .expired-note {\n      display: block;\n      font-size: 11px;\n      color: #f39c12;\n      margin-top: 2px;\n      font-weight: 500;\n    }\n\n    .expired-summary {\n      margin-top: 20px;\n      padding: 15px;\n      background: #fff3cd;\n      border: 1px solid #ffeaa7;\n      border-radius: 8px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n    }\n\n    .expired-info {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      color: #856404;\n    }\n\n    .expired-info i {\n      color: #f39c12;\n      font-size: 16px;\n    }\n\n    .btn-outline {\n      background: transparent;\n      border: 1px solid #f39c12;\n      color: #f39c12;\n    }\n\n    .btn-outline:hover {\n      background: #f39c12;\n      color: white;\n    }\n\n    @media (max-width: 768px) {\n      .content-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .usuario-content {\n        grid-template-columns: 1fr;\n      }\n\n      .expired-summary {\n        flex-direction: column;\n        gap: 10px;\n        text-align: center;\n      }\n    }"],
